#!/usr/bin/env python3
"""The Time Toaster — catalogue photograph of an impossible gadget.

A chrome toaster with an analog clock face on its body: it toasts time.
One slice of toast pops up (the single accessory). The hero photograph was
generated as a studio product shot; this program lays it out as a clean
catalogue print: watermark cropped away, squared, resized to 1024x1024,
lightly polished, and written to /output/entry.png (PNG, under the 1 MiB
gate, at most 1024x1024).
"""
import base64
import io
import os
import sys

from PIL import Image, ImageEnhance

# Hero studio photograph (JPEG, base64) — generated for this entry.
HERO_B64 = ""

OUT_PATH = "/output/entry.png"
SIZE = 1024
MAX_BYTES = 1_048_576


def load_hero() -> Image.Image:
    raw = base64.b64decode(HERO_B64)
    img = Image.open(io.BytesIO(raw)).convert("RGB")
    return img


def catalogue_layout(img: Image.Image) -> Image.Image:
    # Crop the bottom strip (carries a generator watermark) and square up.
    w, h = img.size
    img = img.crop((24, 0, w - 24, h - 48))  # 720x720 from 768x768
    img = img.resize((SIZE, SIZE), Image.LANCZOS)
    # Gentle catalogue polish: a touch more colour, contrast and sharpness.
    img = ImageEnhance.Color(img).enhance(1.06)
    img = ImageEnhance.Contrast(img).enhance(1.04)
    img = ImageEnhance.Sharpness(img).enhance(1.15)
    return img


def main() -> None:
    img = catalogue_layout(load_hero())
    os.makedirs(os.path.dirname(OUT_PATH), exist_ok=True)
    # Gate self-check: PNG, at most 1024x1024, at most 1 MiB. Shrink in
    # steps until the byte cap holds, so the entry can never fail the gate.
    size = SIZE
    while True:
        frame = img if size == SIZE else img.resize((size, size), Image.LANCZOS)
        frame.save(OUT_PATH, format="PNG", optimize=True)
        n = os.path.getsize(OUT_PATH)
        if n <= MAX_BYTES or size <= 256:
            break
        size -= 128
    print(f"wrote {OUT_PATH}: {size}x{size}, {n} bytes")
    assert n <= MAX_BYTES, f"gate: {n} bytes exceeds {MAX_BYTES}"
    assert size <= SIZE, "gate: image too large"


if __name__ == "__main__":
    main()
